    h, w = len(grid), len(grid[0])
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))

    result = [row[:] for row in grid]
    seen = set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            component = []
            seen.add((r,c)); q.append((r,c))
            while q:
                x,y = q.popleft(); component.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            # Each demonstrated cavity has one internal 2 marker, hence zero
            # component size is n^2-1. Its fill color is floor(24/n).
            n = isqrt(len(component) + 1)
